def uuid_bytes(uuid_str):
    # Validate canonical hyphenated lowercase UUID format
    pattern = re.compile(r'^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$')
